#!/usr/bin/env sh

# Type of keys to generate and install.
PRIMER_STEP_SSHKEYS_TYPE=${PRIMER_STEP_SSHKEYS_TYPE:-ed25519}

PRIMER_STEP_SSHKEYS_RSA_LEN=${PRIMER_STEP_SSHKEYS_RSA_LEN:-4096}
PRIMER_STEP_SSHKEYS_ECDSA_LEN=${PRIMER_STEP_SSHKEYS_ECDSA_LEN:-521}; # This IS 521!

# Marker at the end of the comment of the keys generated by this step. Only keys
# carrying it are removed when cleaning, never keys that existed before.
PRIMER_STEP_SSHKEYS_MARKER="(primer)"

primer_step_sshkeys() {
    case "$1" in
        "option")
            shift;
            [ "$#" = "0" ] && echo "--type"
            while [ $# -gt 0 ]; do
                case "$1" in
                    --type)
                        PRIMER_STEP_SSHKEYS_TYPE=$2; shift 2;;
                    -*)
                        yush_warn "Unknown option: $1 !"; shift 2;;
                    *)
                        break;;
                esac
            done
            ;;
        "install")
            lsb_dist=$(primer_os_distribution)
            case "$lsb_dist" in
                *buntu|*bian)
                    primer_os_dependency ssh-keygen openssh-client;;
                alpine*)
                    primer_os_dependency ssh-keygen openssh-keygen;;
                fedora*)
                    primer_os_dependency ssh-keygen openssh-clients;;
                *)
                    primer_os_dependency ssh-keygen openssh;;
            esac
            yush_info "Creating password-less SSH $PRIMER_STEP_SSHKEYS_TYPE key pairs"
            if ! [ -d "$HOME/.ssh" ]; then
                mkdir -p "$HOME/.ssh"
                chmod 700 "$HOME/.ssh"
            fi
            if [ -f "$HOME/.ssh/id_$PRIMER_STEP_SSHKEYS_TYPE" ]; then
                yush_notice "$HOME/.ssh/id_$PRIMER_STEP_SSHKEYS_TYPE already exists, keeping it"
            else
                _comment="$(id -un)@$(uname -n) $PRIMER_STEP_SSHKEYS_MARKER"
                case "$PRIMER_STEP_SSHKEYS_TYPE" in
                    rsa)
                        ssh-keygen -N "" -t "$PRIMER_STEP_SSHKEYS_TYPE" -b "$PRIMER_STEP_SSHKEYS_RSA_LEN" -C "$_comment" -q -f "$HOME/.ssh/id_$PRIMER_STEP_SSHKEYS_TYPE";;
                    ecdsa)
                        ssh-keygen -N "" -t "$PRIMER_STEP_SSHKEYS_TYPE" -b "$PRIMER_STEP_SSHKEYS_ECDSA_LEN" -C "$_comment" -q -f "$HOME/.ssh/id_$PRIMER_STEP_SSHKEYS_TYPE";;
                    *)
                        ssh-keygen -N "" -t "$PRIMER_STEP_SSHKEYS_TYPE" -C "$_comment" -q -f "$HOME/.ssh/id_$PRIMER_STEP_SSHKEYS_TYPE";;
                esac
            fi
            ;;
        "clean")
            _key=$HOME/.ssh/id_$PRIMER_STEP_SSHKEYS_TYPE
            if [ -f "$_key" ]; then
                # Only remove keys generated by this step, i.e. whose public
                # key ends with the marker.
                if [ -f "${_key}.pub" ] && grep -qF " $PRIMER_STEP_SSHKEYS_MARKER" "${_key}.pub"; then
                    yush_info "Removing ssh key pairs from $_key"
                    rm -f "$_key" "${_key}.pub"
                else
                    yush_warn "$_key was not generated by primer, keeping it"
                fi
            fi
            ;;
    esac
}
